declare(strict_types=1);
require_once __DIR__.'/includes/auth.php';requireAdmin();require_once __DIR__.'/config/conexion.php';$errors=[];$message=$_SESSION['flash']??'';unset($_SESSION['flash']);
function uploadNewsImage(array $file): array { $types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>5*1024*1024||!is_uploaded_file($file['tmp_name']??''))return [null,'La imagen debe ser JPG, PNG o WEBP y pesar como máximo 5 MB.'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($types[$mime])||!getimagesize($file['tmp_name']))return [null,'El archivo no es una imagen permitida.'];$dir=__DIR__.'/uploads/noticias';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))return [null,'No se pudo preparar el directorio de imágenes.'];$name=bin2hex(random_bytes(16)).'.'.$types[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))return [null,'No se pudo guardar la imagen.'];return ['uploads/noticias/'.$name,null]; }
function safeNewsImageDelete(string $path): void { $base=realpath(__DIR__.'/uploads/noticias');$file=realpath(__DIR.'/'.$path);if($base&&$file&&str_starts_with($file,$base.DIRECTORY_SEPARATOR)&&is_file($file))unlink($file); }
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrfValid('admin_news',$_POST['csrf_token']??null))$errors[]='La solicitud no es válida.';else{$action=$_POST['action']??'';$id=(int)($_POST['idNoticia']??0);if($action==='delete'){$q=$pdo->prepare('SELECT imagen FROM noticias WHERE idNoticia=?');$q->execute([$id]);$news=$q->fetch();if(!$news)$errors[]='La noticia no existe.';else{$pdo->prepare('DELETE FROM noticias WHERE idNoticia=?')->execute([$id]);safeNewsImageDelete($news['imagen']);flash('Noticia eliminada.');header('Location: noticias-administracion.php');exit;}}else{$titulo=trim((string)($_POST['titulo']??''));$texto=trim((string)($_POST['texto']??''));$fecha=trim((string)($_POST['fecha']??''));if($titulo===''||$texto===''||!validDate($fecha,false))$errors[]='Título, texto y fecha válida son obligatorios.';if(mb_strlen($titulo)>255)$errors[]='El título no puede superar 255 caracteres.';$old=null;if($action==='update'){$q=$pdo->prepare('SELECT imagen FROM noticias WHERE idNoticia=?');$q->execute([$id]);$old=$q->fetch();if(!$old)$errors[]='La noticia no existe.';}$imagePath=$old['imagen']??null;$newImage=false;if(($_FILES['imagen']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){[$imagePath,$uploadError]=uploadNewsImage($_FILES['imagen']);if($uploadError)$errors[]=$uploadError;else $newImage=true;}elseif($action==='create')$errors[]='Debes seleccionar una imagen.';if(!$errors)try{if($action==='create')$pdo->prepare('INSERT INTO noticias (titulo,imagen,texto,fecha,idUser) VALUES (?,?,?,?,?)')->execute([$titulo,$imagePath,$texto,$fecha,(int)$_SESSION['idUser']]);else $pdo->prepare('UPDATE noticias SET titulo=?,imagen=?,texto=?,fecha=? WHERE idNoticia=?')->execute([$titulo,$imagePath,$texto,$fecha,$id]);if($newImage&&$old)safeNewsImageDelete($old['imagen']);flash($action==='create'?'Noticia publicada.':'Noticia actualizada.');header('Location: noticias-administracion.php');exit;}catch(PDOException $e){if($newImage)safeNewsImageDelete($imagePath);$errors[]='No se pudo guardar la noticia. El título debe ser único.';}}}}
$news=$pdo->query('SELECT n.*,d.nombre,d.apellidos FROM noticias n INNER JOIN users_data d ON d.idUser=n.idUser ORDER BY n.fecha DESC')->fetchAll();$editId=(int)($_GET['editar']??0);$editing=null;foreach($news as $n)if($n['idNoticia']===$editId)$editing=$n;$tituloPagina='Administración de noticias | Salud Cercana';require __DIR__.'/includes/header.php';
?>
<main class="content-section"><div class="section-heading"><p class="eyebrow">Administración</p><h1>Noticias</h1></div><?php if($message):?><p class="alert alert-success"><?=e($message)?></p><?php endif;?><?php foreach($errors as $error):?><p class="alert alert-error"><?=e($error)?></p><?php endforeach;?><section class="form-card"><h2><?=$editing?'Editar noticia':'Crear noticia'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrfToken('admin_news'))?>"><input type="hidden" name="action" value="<?=$editing?'update':'create'?>"><?php if($editing):?><input type="hidden" name="idNoticia" value="<?=$editing['idNoticia']?>"><?php endif;?><div class="form-grid"><label class="full-width">Título<input name="titulo" maxlength="255" required value="<?=e($editing['titulo']??'')?>"></label><label>Fecha<input type="date" name="fecha" required value="<?=e($editing['fecha']??date('Y-m-d'))?>"></label><label>Imagen (JPG, PNG o WEBP; máximo 5 MB)<input type="file" name="imagen" accept="image/jpeg,image/png,image/webp" <?=$editing?'':'required'?>></label><label class="full-width">Texto<textarea name="texto" required><?=e($editing['texto']??'')?></textarea></label></div><button class="button"><?=$editing?'Guardar cambios':'Publicar noticia'?></button><?php if($editing):?> <a href="noticias-administracion.php">Cancelar</a><?php endif;?></form></section><section class="spaced-card"><h2>Noticias publicadas</h2><div class="table-wrap"><table><thead><tr><th>Imagen</th><th>Título</th><th>Fecha</th><th>Autor</th><th>Acciones</th></tr></thead><tbody><?php foreach($news as $n):?><tr><td><img class="thumb" src="<?=e($n['imagen'])?>" alt=""></td><td><?=e($n['titulo'])?></td><td><?=e($n['fecha'])?></td><td><?=e($n['nombre'].' '.$n['apellidos'])?></td><td><a href="noticias-administracion.php?editar=<?=$n['idNoticia']?>">Editar</a><form class="inline-form" method="post" onsubmit="return confirm('¿Eliminar esta noticia?');"><input type="hidden" name="csrf_token" value="<?=e(csrfToken('admin_news'))?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="idNoticia" value="<?=$n['idNoticia']?>"><button class="link-button">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
